from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(status="captured", amt="80.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); outage_refund(p,Decimal("30.00"),T0); print(p.refunded_amount,p.status)
outage_refund(p,Decimal("50.00"),T0); print(p.refunded_amount,p.status)
# over refund
p=mk()
try: outage_refund(p,Decimal("80.01"),T0)
except BillingError as e: print("over:",e.code)
# non-captured
try: outage_refund(mk("authorized"),Decimal("1.00"),T0)
except BillingError as e: print("state:",e.code)
# non-positive
for a in ("0.00","-1.00"):
    try: outage_refund(mk(),Decimal(a),T0)
    except BillingError as e: print("amt:",a,e.code)
# banker's rounding 0.125 -> 0.12
p=mk(); outage_refund(p,Decimal("0.125"),T0); print("round:",p.refunded_amount)
# audit
print("audit:",audit.events("payment_refunded")[-1]["event"])
EOF"}

